From 6340252913009acb778cc29a606477504a941776 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:14:01 +0100
Subject: [PATCH] desktoppackage: keep the old desktop visible while switching
 activities

The old activity's desktop is hidden as soon as the containment changes,
so the new one slid in over an empty black window. Show it again while
the switch animation runs, so the new desktop slides over the old one.

BUG: 476406
---
 desktoppackage/contents/views/Desktop.qml | 1 +
 1 file changed, 1 insertion(+)

diff --git a/desktoppackage/contents/views/Desktop.qml b/desktoppackage/contents/views/Desktop.qml
index 1be09364ef..f58d2b478b 100644
--- a/desktoppackage/contents/views/Desktop.qml
+++ b/desktoppackage/contents/views/Desktop.qml
@@ -356,6 +356,7 @@ Item {
                 if (internal.oldContainment) {
                     internal.oldContainment.z = 0;
                     internal.oldContainment.x = 0;
+                    internal.oldContainment.visible = true;
                 }
             }
         }
